), positioned as (
  select id,name,category,latitude,longitude,evidence,
    (longitude-6.97912)*111320*cos(radians(5.39245)) as local_x,
    (5.39245-latitude)*111132 as local_z
  from source_places
)
insert into public.campus_locations
  (id,name,category,latitude,longitude,local_x,local_z,position_status,evidence)
select id,name,category,latitude,longitude,local_x,local_z,'verified',jsonb_build_array(evidence)
from positioned
on conflict (id) do update set
  name=excluded.name,category=excluded.category,latitude=excluded.latitude,longitude=excluded.longitude,
  local_x=excluded.local_x,local_z=excluded.local_z,position_status='verified',
  evidence=excluded.evidence,updated_at=now();
